code.java:
class Solution {
    public int countQuadruplets(int[] nums){
        int answer=0,n=nums.length;
        for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)for(int c=b+1;c<n;c++)for(int d=c+1;d<n;d++)if(nums[a]+nums[b]+nums[c]==nums[d])answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countQuadruplets(nums:IntArray):Int{
        var answer=0;
        for(a in nums.indices)for(b in a+1 until nums.size)for(c in b+1 until nums.size)for(d in c+1 until nums.size)if(nums[a]+nums[b]+nums[c]==nums[d])answer++;
        return answer
    }
}

